/// <summary>
/// AVA
/// </summary>
/// <param name = "_purchParmLine">PurchParmLine</param>
/// <param name = "_isCorrection">boolean</param>
public void postReportFinish(PurchParmLine _purchParmLine, boolean _isCorrection)
{
    if (isConfigurationkeyEnabled(configurationKeyNum(AVASCP)))
    {
        AVASCPSubcontractedProdBOMView  prodBOMView;
        //AVASCPProdMultiReportFinished   prodMultiReportFinished;
        //ProdParmReportFinished          prodParmReportFinished;
        //Args                            args = new Args();
        ProdTable                       prodTable;

        if (_purchParmLine.AVALicensePlateId)
        {
            select firstonly ProdId, OprNum from prodBOMView
                where prodBOMView.InventRefTransId == _purchParmLine.InventTransId;

            if (prodBOMView.ProdId)
            {
                prodTable = ProdTable::find(prodBOMView.ProdId, true);
                if (prodTable.RecId)
                {
                    ttsbegin;
                    prodTable.AVALicensePlateId = _purchParmLine.AVALicensePlateId;
                    prodTable.doUpdate();
                    ttscommit;
                }
            }
        }
    }
    next postReportFinish(_purchParmLine, _isCorrection);
}
